### 4. Guía de Refactorización Preventiva (Store & Componente)

Para garantizar que el código corregido cumpla con la calidad requerida, la implementación en `useCashierKanbanStore` debe estructurarse utilizando referencias estables (`useRef` o variables fuera del ciclo de render para las instancias de canales):

```typescript
// Patrón recomendado para el Store / Hook
import { create } from 'zustand';
import { supabase } from '../lib/supabase';
import { CashierRealtimePayloadSchema } from '../schemas/cashier';

interface KanbanState {
  realtimeStatus: 'IDLE' | 'SUBSCRIBED' | 'ERROR';
  activeChannelsCount: number;
  initializeRealtime: (tenantId: string) => void;
  resetStore: () => void;
}

let channelInstance: any = null; // Instancia singleton fuera del render reactivo

export const useCashierKanbanStore = create<KanbanState>((set, get) => ({
  realtimeStatus: 'IDLE',
  activeChannelsCount: 0,

  initializeRealtime: (tenantId: string) => {
    if (channelInstance) return; // Prevenir múltiples suscripciones

    channelInstance = supabase
      .channel(`kanban_tenant_${tenantId}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'cash_registers' }, (payload) => {
        const validation = CashierRealtimePayloadSchema.safeParse(payload);
        if (!validation.success) {
          console.error('Payload de realtime inválido:', validation.error);
          return;
        }
        // Lógica segura de actualización de estado
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          set({ realtimeStatus: 'SUBSCRIBED', activeChannelsCount: 1 });
        }
      });
  },

  resetStore: () => {
    if (channelInstance) {
      supabase.removeChannel(channelInstance);
      channelInstance = null;
    }
    set({ realtimeStatus: 'IDLE', activeChannelsCount: 0 });
  },
}));
```

